def sort_list(lst):
    def quick_sort(sub_lst):
        if len(sub_lst) <= 1:
            return sub_lst
        pivot = sub_lst[len(sub_lst) // 2]
        left = [x for x in sub_lst if x < pivot]
        middle = [x for x in sub_lst if x == pivot]
        right = [x for x in sub_lst if x > pivot]
        return quick_sort(left) + middle + quick_sort(right)

    return quick_sort(lst)
```

