    highs = [el for el in lst if el > pivot]
    pivots = [el for el in lst if el == pivot]

    if k < len(lows):
        return quickselect_median(lows, k)
    elif k < len(lows) + len(pivots):
        return pivots[0]
    else:
        return quickselect_median(highs, k - len(lows) - len(pivots))
